# calc.py
from fractions import Fraction


class CalcError(Exception):
    def __init__(self, message, position):
        super().__init__(message)
        self.position = position


class Token:
    def __init__(self, type, value, position):
        self.type = type  # 'number', 'op', 'lparen', 'rparen'
        self.value = value
        self.position = position


def tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] in ' \t':
            i += 1
            continue
        if expr[i].isdigit():
            j = i + 1
            while j < n and expr[j].isdigit():
                j += 1
            if j < n and expr[j] == '.':
                j += 1
                if j >= n or not expr[j].isdigit():
                    raise CalcError(f"Invalid number at position {i}", i)
                while j < n and expr[j].isdigit():
                    j += 1
            tokens.append(Token('number', expr[i:j], i))
            i = j
        elif expr[i] in '+-*/':
            tokens.append(Token('op', expr[i], i))
            i += 1
        elif expr[i] == '(':
            tokens.append(Token('lparen', '(', i))
            i += 1
        elif expr[i] == ')':
            tokens.append(Token('rparen', ')', i))
            i += 1
        else:
            raise CalcError(f"Invalid character at position {i}", i)
    return tokens


def evaluate(expr: str) -> Fraction:
    tokens = tokenize(expr)

    # Parser using recursive descent
    class Parser:
        def __init__(self, tokens, expr_len):
            self.tokens = tokens
            self.pos = 0
            self.expr_len = expr_len

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            token = self.tokens[self.pos]
            self.pos += 1
            return token

        def parse(self):
            result = self.parse_expr()
            if self.pos < len(self.tokens):
                # Extra token after expression
                tok = self.tokens[self.pos]
                raise CalcError("Unexpected token", tok.position)
            return result

        def parse_expr(self):
            """Parses addition/subtraction level"""
            left = self.parse_term()
            while self.peek() and self.peek().type == 'op' and self.peek().value in ('+', '-'):
                op_token = self.consume()
                right = self.parse_term()
                if op_token.value == '+':
                    left = left + right
                else:
                    left = left - right
            return left

        def parse_term(self):
            """Parses multiplication/division level"""
            left = self.parse_factor()
            while self.peek() and self.peek().type == 'op' and self.peek().value in ('*', '/'):
                op_token = self.consume()
                right = self.parse_factor()
                if op_token.value == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op_token.position)
                    left = left / right
            return left

        def parse_factor(self):
            """Parses unary minus and primary"""
            if self.peek() and self.peek().type == 'op' and self.peek().value == '-':
                self.consume()
                factor = self.parse_factor()
                return -factor
            return self.parse_primary()

        def parse_primary(self):
            token = self.peek()
            if token is None:
                raise CalcError("Unexpected end of expression", self.expr_len)
            if token.type == 'number':
                self.consume()
                return Fraction(token.value)
            if token.type == 'lparen':
                self.consume()
                if self.peek() is None:
                    raise CalcError("Unexpected end of expression", self.expr_len)
                expr = self.parse_expr()
                if self.peek() is None:
                    raise CalcError("Expected closing parenthesis", self.expr_len)
                if self.peek().type != 'rparen':
                    tok = self.peek()
                    raise CalcError("Expected closing parenthesis", tok.position)
                self.consume()
                return expr
            raise CalcError("Unexpected token", token.position)

    parser = Parser(tokens, len(expr))

    # Check for empty expression
    if not tokens:
        raise CalcError("Empty expression", 0)

    result = parser.parse()
    return result
