# calc.py
from fractions import Fraction


class CalcError(Exception):
    def __init__(self, message, position):
        super().__init__(message)
        self.position = position


class Token:
    def __init__(self, type, value, position):
        self.type = type  # 'number', 'op', 'lparen', 'rparen', 'name', 'comma', 'starstar'
        self.value = value
        self.position = position


def tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] in ' \t':
            i += 1
            continue
        if expr[i].isdigit():
            j = i + 1
            while j < n and expr[j].isdigit():
                j += 1
            if j < n and expr[j] == '.':
                j += 1
                if j >= n or not expr[j].isdigit():
                    raise CalcError(f"Invalid number at position {i}", i)
                while j < n and expr[j].isdigit():
                    j += 1
            tokens.append(Token('number', expr[i:j], i))
            i = j
        elif expr[i] == '*':
            if i + 1 < n and expr[i + 1] == '*':
                tokens.append(Token('starstar', '**', i))
                i += 2
            else:
                tokens.append(Token('op', '*', i))
                i += 1
        elif expr[i] in '+-/':
            tokens.append(Token('op', expr[i], i))
            i += 1
        elif expr[i] == '(':
            tokens.append(Token('lparen', '(', i))
            i += 1
        elif expr[i] == ')':
            tokens.append(Token('rparen', ')', i))
            i += 1
        elif expr[i] == ',':
            tokens.append(Token('comma', ',', i))
            i += 1
        elif expr[i].isalpha() or expr[i] == '_':
            j = i + 1
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(Token('name', expr[i:j], i))
            i = j
        else:
            raise CalcError(f"Invalid character at position {i}", i)
    return tokens


def evaluate(expr: str, variables=None) -> Fraction:
    tokens = tokenize(expr)

    class Parser:
        def __init__(self, tokens, expr_len, variables):
            self.tokens = tokens
            self.pos = 0
            self.expr_len = expr_len
            self.variables = variables

        def peek(self, offset=0):
            idx = self.pos + offset
            if idx < len(self.tokens):
                return self.tokens[idx]
            return None

        def consume(self):
            token = self.tokens[self.pos]
            self.pos += 1
            return token

        def parse(self):
            result = self.parse_expr()
            if self.pos < len(self.tokens):
                tok = self.tokens[self.pos]
                raise CalcError("Unexpected token", tok.position)
            return result

        def parse_expr(self):
            """Parses addition/subtraction level"""
            left = self.parse_term()
            while self.peek() and self.peek().type == 'op' and self.peek().value in ('+', '-'):
                op_token = self.consume()
                right = self.parse_term()
                if op_token.value == '+':
                    left = left + right
                else:
                    left = left - right
            return left

        def parse_term(self):
            """Parses multiplication/division level"""
            left = self.parse_power()
            while self.peek() and self.peek().type == 'op' and self.peek().value in ('*', '/'):
                op_token = self.consume()
                right = self.parse_power()
                if op_token.value == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op_token.position)
                    left = left / right
            return left

        def parse_power(self):
            """Parses exponentiation level (right-associative)"""
            base = self.parse_unary()
            if self.peek() and self.peek().type == 'starstar':
                op_token = self.consume()
                # Right-associative: parse_power for the exponent
                exponent = self.parse_power()
                return self._power(base, exponent, op_token.position)
            return base

        def parse_unary(self):
            """Parses unary minus"""
            if self.peek() and self.peek().type == 'op' and self.peek().value == '-':
                self.consume()
                factor = self.parse_unary()
                return -factor
            return self.parse_primary()

        def parse_primary(self):
            token = self.peek()
            if token is None:
                raise CalcError("Unexpected end of expression", self.expr_len)

            if token.type == 'number':
                self.consume()
                return Fraction(token.value)

            if token.type == 'name':
                # Check if it's a function call (name followed by '(' possibly with spaces)
                name_token = self.consume()
                name = name_token.value
                name_pos = name_token.position

                # Check if next token is 'lparen' (possibly after spaces, but tokenizer skips spaces)
                next_tok = self.peek()
                if next_tok and next_tok.type == 'lparen':
                    # Function call
                    return self._parse_function_call(name, name_pos)
                else:
                    # Variable
                    if self.variables is None:
                        raise CalcError(f"Unknown variable '{name}'", name_pos)
                    if name not in self.variables:
                        raise CalcError(f"Unknown variable '{name}'", name_pos)
                    val = self.variables[name]
                    if isinstance(val, int):
                        return Fraction(val)
                    return val

            if token.type == 'lparen':
                self.consume()
                if self.peek() is None:
                    raise CalcError("Unexpected end of expression", self.expr_len)
                expr = self.parse_expr()
                if self.peek() is None:
                    raise CalcError("Expected closing parenthesis", self.expr_len)
                if self.peek().type != 'rparen':
                    tok = self.peek()
                    raise CalcError("Expected closing parenthesis", tok.position)
                self.consume()
                return expr

            raise CalcError("Unexpected token", token.position)

        def _parse_function_call(self, name, name_pos):
            """Parse function call: name(arg1, arg2, ...)"""
            # Already consumed the name token
            # Next token should be 'lparen'
            lparen = self.consume()
            if lparen.type != 'lparen':
                raise CalcError("Expected '('", lparen.position)

            args = []
            if self.peek() and self.peek().type == 'rparen':
                # Empty argument list
                self.consume()
            else:
                # Parse first argument
                args.append(self.parse_expr())
                while self.peek() and self.peek().type == 'comma':
                    self.consume()
                    args.append(self.parse_expr())
                # Now expect rparen
                if self.peek() is None:
                    raise CalcError("Unexpected end of expression", self.expr_len)
                if self.peek().type != 'rparen':
                    tok = self.peek()
                    raise CalcError("Expected ',' or ')'", tok.position)
                self.consume()

            # Evaluate function
            return self._eval_function(name, args, name_pos)

        def _eval_function(self, name, args, name_pos):
            if name == 'abs':
                if len(args) != 1:
                    raise CalcError("abs() takes exactly 1 argument", name_pos)
                return abs(args[0])
            elif name == 'min':
                if len(args) < 1:
                    raise CalcError("min() takes at least 1 argument", name_pos)
                return min(args)
            elif name == 'max':
                if len(args) < 1:
                    raise CalcError("max() takes at least 1 argument", name_pos)
                return max(args)
            else:
                raise CalcError(f"Unknown function '{name}'", name_pos)

        def _power(self, base, exponent, pos):
            """Compute base ** exponent with checks"""
            # Check if exponent is a whole number (integer)
            if exponent.denominator != 1:
                raise CalcError("Exponent must be an integer", pos)
            exp_int = int(exponent)

            # Check for 0 ** negative
            if base == 0 and exp_int < 0:
                raise CalcError("Zero to negative power", pos)

            # Compute power
            if exp_int >= 0:
                # Integer exponent
                result = Fraction(base.numerator ** exp_int, base.denominator ** exp_int)
            else:
                # Negative exponent: 1 / (base ** |exp|)
                abs_exp = -exp_int
                denom_val = Fraction(base.numerator ** abs_exp, base.denominator ** abs_exp)
                if denom_val == 0:
                    raise CalcError("Zero to negative power", pos)
                result = 1 / denom_val
            return result

    parser = Parser(tokens, len(expr), variables)

    if not tokens:
        raise CalcError("Empty expression", 0)

    result = parser.parse()
    return result
