# cron.py

import datetime
import calendar


def next_run(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Return the next time a standard five-field cron expression fires,
    strictly after the given datetime.
    """
    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    # Parse each field
    minutes = _parse_field(fields[0], 0, 59, 'minute')
    hours = _parse_field(fields[1], 0, 23, 'hour')
    doms = _parse_field(fields[2], 1, 31, 'day of month')
    months = _parse_field(fields[3], 1, 12, 'month')
    dows = _parse_field(fields[4], 0, 7, 'day of week')

    # Normalize DOW: 7 -> 0 (Sunday)
    dows = {d % 7 for d in dows}

    # Determine which day fields are restricted
    dom_restricted = not fields[2].startswith('*')
    dow_restricted = not fields[4].startswith('*')

    # Start from the next minute after 'after' (seconds/microseconds set to 0)
    # We need strictly later, so start from the next minute
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    # Iterate to find the next matching time
    # We'll search forward in time
    for _ in range(0, 366 * 24 * 60):  # Maximum reasonable search window (about a year)
        # Check month
        if current.month not in months:
            # Advance to the first day of the next valid month
            current = _advance_to_next_valid_month(current, months)
            continue

        # Check day (day of month or day of week)
        if not _day_matches(current, doms, months, dows, dom_restricted, dow_restricted):
            current = current.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            continue

        # Check hour
        if current.hour not in hours:
            current = _advance_to_next_valid_hour(current, hours)
            continue

        # Check minute
        if current.minute not in minutes:
            current = _advance_to_next_valid_minute(current, minutes)
            continue

        # All fields match
        return current

    raise ValueError("No valid time found within the search window")


def _parse_field(field: str, min_val: int, max_val: int, field_name: str) -> set:
    """Parse a single cron field and return a set of matching integer values."""
    if not field:
        raise ValueError(f"Empty field")

    items = field.split(',')
    result = set()

    for item in items:
        if not item:
            raise ValueError(f"Empty item in field")

        result.update(_parse_item(item, min_val, max_val, field_name))

    return result


def _parse_item(item: str, min_val: int, max_val: int, field_name: str) -> set:
    """Parse a single item within a cron field."""
    if '/' in item:
        # Handle step
        if item.count('/') != 1:
            raise ValueError(f"Invalid step in {item}")

        base_part, step_str = item.split('/')

        # Parse step
        if not step_str.isdigit():
            raise ValueError(f"Step must be a positive integer, got {step_str}")
        step = int(step_str)
        if step <= 0:
            raise ValueError(f"Step must be a positive integer, got {step}")

        # Parse base
        if base_part == '*':
            start = min_val
            end = max_val
        elif '-' in base_part:
            start, end = _parse_range(base_part, min_val, max_val, field_name)
        else:
            # N/S is not allowed (e.g., 5/10)
            raise ValueError(f"N/S is not a valid form in {item}")

        result = set()
        current = start
        while current <= end:
            result.add(current)
            current += step
        return result

    elif '-' in item:
        start, end = _parse_range(item, min_val, max_val, field_name)
        return set(range(start, end + 1))

    elif item == '*':
        return set(range(min_val, max_val + 1))

    else:
        # Single value
        if not item.isdigit():
            raise ValueError(f"Invalid value in {item}")
        value = int(item)
        if value < min_val or value > max_val:
            raise ValueError(f"Value {value} outside range [{min_val}, {max_val}]")
        return {value}


def _parse_range(item: str, min_val: int, max_val: int, field_name: str) -> tuple:
    """Parse a range like A-B and return (start, end)."""
    parts = item.split('-')
    if len(parts) != 2:
        raise ValueError(f"Invalid range {item}")

    start_str, end_str = parts
    if not start_str.isdigit() or not end_str.isdigit():
        raise ValueError(f"Invalid range values in {item}")

    start = int(start_str)
    end = int(end_str)

    if start < min_val or start > max_val:
        raise ValueError(f"Value {start} outside range [{min_val}, {max_val}]")
    if end < min_val or end > max_val:
        raise ValueError(f"Value {end} outside range [{min_val}, {max_val}]")
    if start > end:
        raise ValueError(f"Range start {start} > end {end}")

    return (start, end)


def _day_matches(dt: datetime.datetime, doms: set, months: set, dows: set, dom_restricted: bool, dow_restricted: bool) -> bool:
    """Check if the day part of dt matches the cron specification."""
    dom = dt.day
    dow = dt.weekday()
    # Python weekday: Monday=0, Sunday=6
    # Cron DOW: Sunday=0, Monday=1, ..., Saturday=6
    # Convert Python weekday to cron DOW
    cron_dow = (dow + 1) % 7

    dom_match = dom in doms
    dow_match = cron_dow in dows

    if dom_restricted and dow_restricted:
        # Both restricted: day matches if it matches either
        return dom_match or dow_match
    else:
        # At least one is not restricted (starts with *): day must match both
        # Since a non-restricted field matches all values, this simplifies
        # to matching the restricted one (or both if neither is restricted, but that's covered by both being non-restricted matching all)
        return dom_match and dow_match


def _advance_to_next_valid_month(current: datetime.datetime, months: set) -> datetime.datetime:
    """Advance to the first minute of the next valid month."""
    month = current.month
    year = current.year

    # Find the next valid month
    while True:
        month += 1
        if month > 12:
            month = 1
            year += 1

        if month in months:
            return datetime.datetime(year, month, 1, 0, 0, 0)


def _advance_to_next_valid_hour(current: datetime.datetime, hours: set) -> datetime.datetime:
    """Advance to the next valid hour, resetting minute to 0."""
    hour = current.hour

    # Find the next valid hour in the current day or next day
    sorted_hours = sorted(hours)

    # Try to find a valid hour in the current day
    for h in sorted_hours:
        if h > hour:
            return current.replace(hour=h, minute=0, second=0, microsecond=0)

    # No valid hour in the rest of the current day, go to next day
    next_day = current + datetime.timedelta(days=1)
    next_day = next_day.replace(hour=0, minute=0, second=0, microsecond=0)

    # Find the first valid hour
    if sorted_hours:
        first_hour = sorted_hours[0]
        return next_day.replace(hour=first_hour)

    # This shouldn't happen since hours set should be non-empty
    raise ValueError("No valid hours")


def _advance_to_next_valid_minute(current: datetime.datetime, minutes: set) -> datetime.datetime:
    """Advance to the next valid minute, keeping the same hour and day."""
    minute = current.minute

    sorted_minutes = sorted(minutes)

    # Try to find a valid minute in the current hour
    for m in sorted_minutes:
        if m > minute:
            return current.replace(minute=m, second=0, microsecond=0)

    # No valid minute in the current hour, go to next hour
    next_hour = current + datetime.timedelta(hours=1)
    next_hour = next_hour.replace(minute=0, second=0, microsecond=0)

    # Find the first valid minute
    if sorted_minutes:
        first_minute = sorted_minutes[0]
        return next_hour.replace(minute=first_minute)

    # This shouldn't happen since minutes set should be non-empty
    raise ValueError("No valid minutes")
