# trie.py

class TrieNode:
    def __init__(self):
        self.children: dict[str, TrieNode] = {}
        self.words: list[tuple[float, str]] = []  # list of (weight, original_spelling)
        # We'll store words at the node that corresponds to the end of the word
        # But for autocomplete, we need all words under a prefix
        # So we'll store words in each node as a list of (weight, spelling) for words ending here
        # and also need to collect all words in subtree when completing a prefix.
        # For efficiency, we can store words at leaf-like nodes or use a different approach.
        # Let's store words at the node representing the full casefolded form of the word.
        # When completing, we traverse to the prefix node and collect all words in its subtree.
        pass


class Autocomplete:
    def __init__(self):
        self.root = TrieNode()
        self._count = 0

    def add(self, word: str, weight: float = 1) -> None:
        if not word:
            raise ValueError("word must not be empty")
        casefolded = word.casefold()
        # Check if word already exists
        if self._exists(casefolded):
            self.delete_by_casefold(casefolded)
        # Insert the word
        node = self.root
        for ch in casefolded:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        # Store the word with its weight at this node
        node.words.append((weight, word))
        self._count += 1

    def _exists(self, casefolded: str) -> bool:
        node = self.root
        for ch in casefolded:
            if ch not in node.children:
                return False
            node = node.children[ch]
        # Check if any word stored here has this casefolded form
        # Since we replace on add, there should be at most one, but let's check
        return len(node.words) > 0

    def delete_by_casefold(self, casefolded: str) -> bool:
        # Find and remove the node's words
        node = self.root
        path = []
        for ch in casefolded:
            if ch not in node.children:
                return False
            path.append((node, ch))
            node = node.children[ch]
        if len(node.words) == 0:
            return False
        node.words.clear()
        self._count -= 1
        # Optional: clean up empty nodes (not strictly necessary for correctness)
        return True

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        casefolded_prefix = prefix.casefold()
        node = self.root
        for ch in casefolded_prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        # Collect all words in the subtree rooted at node
        results: list[tuple[float, str, str]] = []  # (weight, casefolded, original)
        self._collect_words(node, results)
        # Sort by weight descending, then by casefolded ascending
        results.sort(key=lambda x: (-x[0], x[1]))
        # Return up to k original spellings
        return [original for _, _, original in results[:k]]

    def _collect_words(self, node: TrieNode, results: list[tuple[float, str, str]]) -> None:
