    if result is None:
        return None
    return _helper_to_grid(result)


def count_solutions(grid, limit: int = 2) -> int:
    """Number of solutions, capped at limit (so min(solutions, limit)).

    Invalid grids have 0 solutions. ValueError if grid is malformed or
    limit < 1. The argument is never modified.
    """
    _validate_grid(grid)
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
        raise ValueError("limit must be an integer >= 1")
    if not is_valid(grid):
        return 0
    cand = _candidates_from_grid(grid)
    if not _propagate(cand):
        return 0
    return _solve_helper(cand, limit)
