import datetime
from decimal import Decimal
from .models import Item, Movement, UnknownItemError, InsufficientStockError


def _validate_qty(qty):
    if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
        raise ValueError("qty must be a positive int")


def _validate_day(day, last_day):
    if last_day is not None and day < last_day:
        raise ValueError("day cannot be earlier than the last recorded movement day")


def _to_decimal(value, name="unit_cost"):
    if isinstance(value, float):
        raise TypeError(f"{name} must not be a float")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        return Decimal(value)
    if isinstance(value, str):
        try:
            return Decimal(value)
        except Exception as exc:
            raise ValueError(f"invalid {name}: {value!r}") from exc
    raise TypeError(f"unsupported type for {name}: {type(value).__name__}")


class Ledger:
    def __init__(self):
        self._items: dict[str, Item] = {}
        self._movements: list[Movement] = []

    # --- item registry ---
    def add_item(self, item: Item) -> None:
        if item.sku in self._items:
            raise ValueError(f"item with SKU {item.sku!r} already exists")
        self._items[item.sku] = item

    def item(self, sku: str) -> Item:
        try:
            return self._items[sku]
        except KeyError:
            raise UnknownItemError(f"unknown SKU: {sku!r}") from None

    def items(self) -> list[Item]:
        return sorted(self._items.values(), key=lambda it: it.sku)

    def locations(self) -> list[str]:
        locs: set[str] = set()
        for m in self._movements:
            locs.add(m.location)
            if m.to_location is not None:
                locs.add(m.to_location)
        return sorted(locs)

    # --- internal ---
    def _last_day(self):
        return self._movements[-1].day if self._movements else None

    def _on_hand_internal(self, sku: str, location=None, as_of=None):
        if sku not in self._items:
            raise UnknownItemError(f"unknown SKU: {sku!r}")
        total = 0
        for m in self._movements:
            if m.sku != sku:
                continue
            if as_of is not None and m.day > as_of:
                continue
            if m.kind == "receive":
                if location is None or m.location == location:
                    total += m.qty
            elif m.kind == "issue":
                if location is None or m.location == location:
                    total -= m.qty
            elif m.kind == "transfer":
                if location is None:
                    # transfer moves out of location and into to_location: net zero overall
                    continue
                elif m.location == location:
                    total -= m.qty
                elif m.to_location == location:
                    total += m.qty
        return total

    def _record(self, movement: Movement) -> Movement:
        self._movements.append(movement)
        return movement

    # --- public recording API ---
    def receive(self, day, sku, location, qty, unit_cost) -> Movement:
        # 1. unknown item
        if sku not in self._items:
            raise UnknownItemError(f"unknown SKU: {sku!r}")
        # 2. qty check
        _validate_qty(qty)
        # day check (uses last recorded movement day)
        _validate_day(day, self._last_day())
        # unit_cost conversion/validation (not specified in error order but must occur before recording)
        cost = _to_decimal(unit_cost, "unit_cost")
        if cost < 0:
            raise ValueError("unit_cost must not be negative")
        # 4. never applies to receive
        seq = len(self._movements) + 1
        mv = Movement(
            seq=seq, day=day, kind="receive", sku=sku, qty=qty,
            location=location, to_location=None, unit_cost=cost,
        )
        return self._record(mv)

    def issue(self, day, sku, location, qty) -> Movement:
        if sku not in self._items:
            raise UnknownItemError(f"unknown SKU: {sku!r}")
        _validate_qty(qty)
        _validate_day(day, self._last_day())
        held = self._on_hand_internal(sku, location=location)
        if qty > held:
            raise InsufficientStockError(
                f"insufficient stock for {sku!r} in {location!r}: have {held}, need {qty}"
            )
        seq = len(self._movements) + 1
        mv = Movement(
            seq=seq, day=day, kind="issue", sku=sku, qty=qty,
            location=location, to_location=None, unit_cost=None,
        )
        return self._record(mv)

    def transfer(self, day, sku, from_location, to_location, qty) -> Movement:
        if from_location == to_location:
            raise ValueError("from_location and to_location must differ")
        if sku not in self._items:
            raise UnknownItemError(f"unknown SKU: {sku!r}")
        _validate_qty(qty)
        _validate_day(day, self._last_day())
        held = self._on_hand_internal(sku, location=from_location)
        if qty > held:
            raise InsufficientStockError(
                f"insufficient stock for {sku!r} in {from_location!r}: have {held}, need {qty}"
            )
        seq = len(self._movements) + 1
        mv = Movement(
            seq=seq, day=day, kind="transfer", sku=sku, qty=qty,
            location=from_location, to_location=to_location, unit_cost=None,
        )
        return self._record(mv)

    # --- query API ---
    def movements(self, sku=None, as_of=None) -> list[Movement]:
        result: list[Movement] = []
        for m in self._movements:
            if sku is not None and m.sku != sku:
                continue
            if as_of is not None and m.day > as_of:
                continue
            result.append(m)
        return result

    def on_hand(self, sku, location=None, as_of=None) -> int:
        return self._on_hand_internal(sku, location=location, as_of=as_of)
