from decimal import Decimal, ROUND_HALF_UP
from .models import UnknownItemError
from .movements import Ledger  # type: ignore
from dataclasses import dataclass


CENTS = Decimal("0.01")


def _quantize(value: Decimal) -> Decimal:
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Valuation:
    qty: int
    value: Decimal
    cogs: Decimal


def fifo(ledger: Ledger, sku: str, as_of=None) -> Valuation:
    if sku not in ledger._items:
        raise UnknownItemError(f"unknown SKU: {sku!r}")

    layers: list[list] = []  # each layer: [remaining_qty:int, unit_cost:Decimal]
    cogs = Decimal(0)

    for m in ledger.movements(sku=sku, as_of=as_of):
        if m.kind == "receive":
            layers.append([m.qty, m.unit_cost])
        elif m.kind == "issue":
            remaining = m.qty
            for layer in layers:
                if remaining <= 0:
                    break
                take = min(layer[0], remaining)
                cogs += Decimal(take) * layer[1]
                layer[0] -= take
                remaining -= take
            # remaining should be 0 because on-hand guarantees sufficiency
        # transfer has no cost effect
    value = Decimal(0)
    qty_total = 0
    for layer in layers:
        qty_total += layer[0]
        value += Decimal(layer[0]) * layer[1]

    return Valuation(qty=qty_total, value=_quantize(value), cogs=_quantize(cogs))


def average(ledger: Ledger, sku: str, as_of=None) -> Valuation:
    if sku not in ledger._items:
        raise UnknownItemError(f"unknown SKU: {sku!r}")

    qty_total = 0
    value = Decimal(0)
    cogs = Decimal(0)

    for m in ledger.movements(sku=sku, as_of=as_of):
        if m.kind == "receive":
            qty_total += m.qty
            value += Decimal(m.qty) * m.unit_cost
        elif m.kind == "issue":
            if qty_total > 0:
                if m.qty == qty_total:
                    cost = value
                else:
                    cost = _quantize(value * Decimal(m.qty) / Decimal(qty_total))
                cogs += cost
                value -= cost
            qty_total -= m.qty
        # transfer has no cost effect

    return Valuation(qty=qty_total, value=_quantize(value), cogs=_quantize(cogs))


def valuate(ledger: Ledger, sku: str, method: str = "fifo", as_of=None) -> Valuation:
    if method == "fifo":
        return fifo(ledger, sku, as_of)
    if method == "average":
        return average(ledger, sku, as_of)
    raise ValueError(f"unknown method: {method!r}")
