import datetime
from decimal import Decimal
from .valuation import valuate
from .movements import Ledger  # type: ignore


def _fmt_money(d: Decimal) -> str:
    return f"{d:.2f}"


def _grouped_report(groups, header, line_fmt, money_cols=(), total_fmt=None, grand_total_fmt=None):
    """Build CSV lines.

    groups: dict[str, list[tuple]] where key is group name and value list is (sorted) rows.
    Each row is a tuple to be formatted by line_fmt.
    money_cols: indices in the row tuple that are money and must be printed with 2 decimals
    total_fmt: function(list_of_rows) -> string for subtotal line of a group
    grand_total_fmt: function(list_of_all_rows) -> string for grand total line
    """
    lines = [header]
    for group_name in sorted(groups.keys()):
        rows = groups[group_name]
        if not rows:
            continue
        # emit row lines
        for row in rows:
            formatted = []
            for i, col in enumerate(row):
                if isinstance(col, Decimal):
                    formatted.append(_fmt_money(col))
                else:
                    formatted.append(str(col))
            lines.append(",".join(formatted))
        # subtotal line
        lines.append(total_fmt(group_name, rows))

    # grand total
    all_rows = [r for g in sorted(groups.keys()) for r in groups[g]]
    lines.append(grand_total_fmt(all_rows))

    return "".join(line + "\n" for line in lines)


def stock_report(ledger: Ledger, as_of=None, location=None) -> str:
    header = "location,sku,qty"

    # Determine which SKUs to include: those with any movement <= as_of
    relevant_skus = {m.sku for m in ledger.movements(as_of=as_of)}

    # Build groups: location -> list of (sku, qty)
    locations = [location] if location is not None else ledger.locations()
    groups: dict[str, list[tuple]] = {}

    for loc in locations:
        rows: list[tuple] = []
        for sku in sorted(relevant_skus):
            qty = ledger.on_hand(sku, location=loc, as_of=as_of)
            if qty != 0:
                rows.append((loc, sku, qty))
        # sort by sku (already sorted by iterating sorted relevant_skus)
        groups[loc] = rows

    def subtotal(group_name: str, rows):
        total_qty = sum(r[2] for r in rows)
        return f"{group_name},TOTAL,{total_qty}"

    def grand_total(all_rows):
        total_qty = sum(r[2] for r in all_rows)
        return f"TOTAL,,{total_qty}"

    return _grouped_report(groups, header, None, money_cols=(),
                           total_fmt=subtotal, grand_total_fmt=grand_total)


def valuation_report(ledger: Ledger, as_of=None, method="fifo", category=None) -> str:
    header = "category,sku,qty,value"

    # invalid method check
    if method not in ("fifo", "average"):
        raise ValueError(f"unknown method: {method!r}")

    # Determine relevant SKUs (any movement <= as_of) and get their items/categories
    relevant_skus = {m.sku for m in ledger.movements(as_of=as_of)}

    # Map category -> list of rows
    groups: dict[str, list[tuple]] = {}
    for sku in sorted(relevant_skus):
        item = ledger.item(sku)
        cat = item.category
        if category is not None and cat != category:
            continue
        v = valuate(ledger, sku, method=method, as_of=as_of)
        if v.qty == 0:
            continue
        groups.setdefault(cat, []).append((cat, sku, v.qty, v.value))

    # Within each category, rows are already sorted by sku because we iterated sorted skus

    def subtotal(group_name: str, rows):
        total_qty = sum(r[2] for r in rows)
        total_val = sum(r[3] for r in rows)
        return f"{group_name},TOTAL,{total_qty},{_fmt_money(total_val)}"

    def grand_total(all_rows):
        total_qty = sum(r[2] for r in all_rows)
        total_val = sum(r[3] for r in all_rows)
        return f"TOTAL,,{total_qty},{_fmt_money(total_val)}"

    return _grouped_report(groups, header, None, money_cols=(),
                           total_fmt=subtotal, grand_total_fmt=grand_total)
