fsm/machine.py
```python
from dataclasses import dataclass
from typing import Any, Callable, Optional, Union


class MachineError(Exception):
    pass


class InvalidTransition(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(f"No transition for event '{event}' from state '{state}'")
        self.state = state
        self.event = event


class GuardRejected(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(f"Guard rejected all transitions for event '{event}' from state '{state}'")
        self.state = state
        self.event = event


@dataclass
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None


@dataclass
class Transition:
    event: str
    source: Union[str, list, tuple]
    target: Optional[str]
    guard: Optional[Callable] = None
    action: Optional[Callable] = None


@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict


class Machine:
    def __init__(self, states, transitions, initial: str, context=None):
        if not states:
            raise ValueError("states must not be empty")

        self._states = {}
        for s in states:
            if isinstance(s, State):
                state_obj = s
            elif isinstance(s, str):
                state_obj = State(name=s)
            else:
                raise ValueError(f"Invalid state: {s}")
            if state_obj.name in self._states:
                raise ValueError(f"Duplicate state name: {state_obj.name}")
            self._states[state_obj.name] = state_obj

        if initial not in self._states:
            raise ValueError(f"Initial state '{initial}' is not a valid state")

        self._transitions = []
        for t in transitions:
            # Validate source
            if isinstance(t.source, str):
                if t.source != '*' and t.source not in self._states:
                    raise ValueError(f"Transition source '{t.source}' is not a valid state")
            elif isinstance(t.source, (list, tuple)):
                for s in t.source:
                    if s not in self._states:
                        raise ValueError(f"Transition source '{s}' is not a valid state")
            else:
                raise ValueError(f"Invalid transition source: {t.source}")

            # Validate target
            if t.target is not None and t.target not in self._states:
                raise ValueError(f"Transition target '{t.target}' is not a valid state")

            self._transitions.append(t)

        self._initial = initial
        self.state = initial
        self.context = context
        self.history = []
        self._listeners = []
        self._in_fire = False

    def fire(self, event: str, **data) -> str:
        if self._in_fire:
            raise MachineError("Cannot call fire while another fire is in progress")

        self._in_fire = True
        try:
            current_state = self.state
            data_dict = data

            # 1. Find candidates
            candidates = []
            for t in self._transitions:
                if t.event != event:
                    continue
                if isinstance(t.source, str):
                    if t.source == '*' or t.source == current_state:
                        candidates.append(t)
                elif isinstance(t.source, (list, tuple)):
                    if current_state in t.source:
                        candidates.append(t)

            if not candidates:
                raise InvalidTransition(current_state, event)

            # 2 & 3. Evaluate guards
            chosen_transition = None
            for t in candidates:
                if t.guard is None:
                    chosen_transition = t
                    break
                ev_obj = Event(name=event, source=current_state, target=t.target if t.target else current_state, data=data_dict)
                if t.guard(self, ev_obj):
                    chosen_transition = t
                    break

            if chosen_transition is None:
                raise GuardRejected(current_state, event)

            # Prepare event object with correct target for internal transitions
            target_state = chosen_transition.target if chosen_transition.target is not None else current_state
            event_obj = Event(name=event, source=current_state, target=target_state, data=data_dict)

            # Execute transition
            if chosen_transition.target is None:
                # Internal transition
                try:
                    if chosen_transition.action is not None:
                        chosen_transition.action(self, event_obj)
                except Exception:
                    self._in_fire = False
                    raise

                # Record history for internal transition
                self.history.append((current_state, event, current_state))

                # Call listeners
                for listener in self._listeners:
                    listener(current_state, event_obj, current_state)

                return current_state
            else:
                # Normal transition
                new_state = chosen_transition.target

                # On exit
                current_state_obj = self._states[current_state]
                try:
                    if current_state_obj.on_exit is not None:
                        current_state_obj.on_exit(self, event_obj)

                    # Action
                    if chosen_transition.action is not None:
                        chosen_transition.action(self, event_obj)

                    # Change state and record history
                    self.state = new_state
                    self.history.append((current_state, event, new_state))

                    # On enter
                    new_state_obj = self._states[new_state]
                    if new_state_obj.on_enter is not None:
                        new_state_obj.on_enter(self, event_obj)

                except Exception:
                    self._in_fire = False
                    raise

                # Call listeners
                for listener in self._listeners:
                    listener(current_state, event_obj, new_state)

                self._in_fire = False
                return new_state

        except Exception:
            self._in_fire = False
            raise
        finally:
            # Ensure _in_fire is cleared if an exception occurred before the explicit clear
            self._in_fire = False

    def can_fire(self, event: str, **data) -> bool:
        current_state = self.state
        data_dict = data

        candidates = []
        for t in self._transitions:
            if t.event != event:
                continue
            if isinstance(t.source, str):
                if t.source == '*' or t.source == current_state:
                    candidates.append(t)
            elif isinstance(t.source, (list, tuple)):
                if current_state in t.source:
                    candidates.append(t)

        if not candidates:
            return False

        for t in candidates:
            if t.guard is None:
                return True
            ev_obj = Event(name=event, source=current_state, target=t.target if t.target else current_state, data=data_dict)
            if t.guard(self, ev_obj):
                return True

        return False

    def available_events(self) -> list:
        current_state = self.state
        events = set()
        for t in self._transitions:
            if isinstance(t.source, str):
                if t.source == '*' or t.source == current_state:
                    events.add(t.event)
            elif isinstance(t.source, (list, tuple)):
                if current_state in t.source:
                    events.add(t.event)
        return sorted(events)

    def on_transition(self, listener: Callable):
        self._listeners.append(listener)

    def reset(self):
        self.state = self._initial
        self.history = []
