import fsm


class VendingError(Exception):
    pass


class SoldOut(VendingError):
    pass


class InsufficientCredit(VendingError):
    pass


class VendingMachine:
    ACCEPTED_COINS = {5, 10, 25, 100}
    COIN_ORDER = [100, 25, 10, 5]

    def __init__(self, products: dict):
        # products: code -> (price, stock)
        self._products = {code: list(val) for code, val in products.items()}
        self._credit = 0
        self._sales = {}
        self._revenue = 0

        # Build FSM
        states = ['idle', 'credit', 'maintenance']

        transitions = [
            fsm.Transition('insert', ['idle', 'credit'], 'credit'),
            fsm.Transition('select', 'credit', 'idle'),
            fsm.Transition('cancel', 'credit', 'idle'),
            fsm.Transition('service', 'idle', 'maintenance'),
            fsm.Transition('restock', 'maintenance', 'maintenance'),
            fsm.Transition('resume', 'maintenance', 'idle'),
        ]

        self.machine = fsm.Machine(states, transitions, initial='idle', context=self)

    @property
    def state(self):
        return self.machine.state

    @property
    def credit(self):
        return self._credit

    @property
    def revenue(self):
        return self._revenue

    def stock(self, code: str) -> int:
        if code not in self._products:
            raise KeyError(code)
        return self._products[code][1]

    def price(self, code: str) -> int:
        if code not in self._products:
            raise KeyError(code)
        return self._products[code][0]

    def sales(self) -> dict:
        return dict(self._sales)

    def _make_change(self, amount: int) -> list:
        change = []
        for coin in self.COIN_ORDER:
            while amount >= coin:
                change.append(coin)
                amount -= coin
        return change

    def insert(self, coin: int) -> int:
        if coin not in self.ACCEPTED_COINS:
            raise ValueError(f"Coin {coin} not accepted")

        def action(machine, event):
            self._credit += coin

        self.machine.fire('insert', action=action)
        return self._credit

    def select(self, code: str) -> list:
        # The state check is handled by the FSM (InvalidTransition if not in credit)

        def guard(machine, event):
            if code not in self._products:
                raise KeyError(code)
            price, stock = self._products[code]
            if stock <= 0:
                raise SoldOut(code)
            if self._credit < price:
                raise InsufficientCredit(f"Need {price}, have {self._credit}")
            return True

        def action(machine, event):
            price, stock = self._products[code]
            change = self._make_change(self._credit - price)
            self._credit = 0
            self._products[code][1] -= 1

            # Update sales and revenue
            self._sales[code] = self._sales.get(code, 0) + 1
            self._revenue += price

            event.data['change'] = change

        self.machine.fire('select', code=code, guard=guard, action=action)
        return self.machine.history[-1][2]  # This is wrong, we need to return change from the action

    # Correction: fire doesn't return the change. We need to store the change in the event data and return it.
    # But fire returns the new state string.
    # Let's re-read: "fire(event: str, **data) -> str takes one transition and returns the new current state"
    # So select must return the change list, not the state.
    # The change is computed in the action and stored in event.data['change'].
    # We can't easily get it out of fire directly if fire only returns the state.
    # However, the action has access to the event object. We can store the result in the machine's context or a local variable via closure.

    # Let's rewrite select to capture the change.

    # Wait, I already defined select above. Let me fix it.

    def select(self, code: str) -> list:  # noqa: F811
        change_holder = []

        def guard(machine, event):
            if code not in self._products:
                raise KeyError(code)
            price, stock = self._products[code]
            if stock <= 0:
                raise SoldOut(code)
            if self._credit < price:
                raise InsufficientCredit(f"Need {price}, have {self._credit}")
            return True

        def action(machine, event):
            price, stock = self._products[code]
            change = self._make_change(self._credit - price)
            self._credit = 0
            self._products[code][1] -= 1

            self._sales[code] = self._sales.get(code, 0) + 1
            self._revenue += price

            change_holder.extend(change)

        self.machine.fire('select', code=code, guard=guard, action=action)
        return change_holder

    def cancel(self) -> list:
        change_holder = []

        def action(machine, event):
            change = self._make_change(self._credit)
            self._credit = 0
            change_holder.extend(change)

        self.machine.fire('cancel', action=action)
        return change_holder

    def service(self) -> None:
        self.machine.fire('service')

    def restock(self, code: str, qty: int, price: int = None) -> None:
        if qty < 1:
            raise ValueError("qty must be >= 1")

        def guard(machine, event):
            if code not in self._products and price is None:
                raise KeyError(f"Code {code} is new and needs a price")
            return True

        def action(machine, event):
            if code in self._products:
                self._products[code][1] += qty
                if price is not None:
                    self._products[code][0] = price
            else:
                self._products[code] = [price, qty]

        self.machine.fire('restock', code=code, qty=qty, price=price, guard=guard, action=action)

    def resume(self) -> None:
        self.machine.fire('resume')
